from six.moves import zip_longest


class GROUP_CONFIG(Config):
    """This class groups two or more configuration parameters."""

    VALIDATOR = IsInstance(Config)
    SELF_ATTRS = ['exists', 'count']

    def __init__(self, *schemas):
        """
        :param schemas: One or more schemas to group.
        """
        super(GROUP_CONFIG, self).__init__()
        for index, each in enumerate(schemas, start=1):
            self._set_attr(index, each, self.VALIDATOR)

    @property
    def count(self):
        """Return number of provided objects."""
        return len(self._attributes)

    @property
    def exists(self):
        """Return True if at least on object was provided."""
        return True if self._attributes else False

    def __iter__(self):
        for tl_config in self._attributes.values():
            yield tl_config

    def __reversed__(self):
        config_indexes = list(reversed(range(1, len(self._attributes) + 1)))
        for config_index in config_indexes:
            yield self._attributes[config_index]

    def __getattr__(self, item):
        if item in self.SELF_ATTRS:
            return super(GROUP_CONFIG, self).__getattribute__(item)
        return getattr(self._attributes[1], item)

    def __getitem__(self, item):
        if isinstance(item, int):
            self._is_index_correct(item)
            return self._attributes[item]
        return self._attributes[1][item]

    def _is_index_correct(self, index):
        if index <= 0 or index > len(self._attributes):
            raise RuntimeError("Schemas are indexed from 1 to number of provided schemas. "
                               "Linker contains schemas in range {}-{}, requested index is {}.".format(1, len(self._attributes), index))


class RF_CONFIG(GROUP_CONFIG):
    """This class describes the configurations for RF and the attached ALD."""
    def __init__(self, *schemas):
        super(RF_CONFIG, self).__init__(*schemas)

    def get_rfs(self, hw_type, hw_instance=None):
        """
        :param string hw_type:          Get the RFs configuration that match the given hw_type.
        :param int hw_instance:         Get the RFs configuration that match the given hw_instance. (Optional)
        :return: list of rfs
        :rtype: list
        """
        if hw_instance:
            return [rf for rf in self._attributes.values() if rf['hw_type'] == hw_type and rf['hw_instance'] == hw_instance]
        return [rf for rf in self._attributes.values() if rf['hw_type'] == hw_type]

    def get_alds(self, hw_type, hw_instance=None):
        """
        :param string hw_type:          Get the ALDs configuration that match the given hw_type.
        :param int hw_instance:         Get the ALDs configuration that match the given hw_instance. (Optional)
        :return: list of alds
        :rtype: list
        """

        if hw_instance:
            return [ald['ald'] for ald in self._attributes.values() if ald['ald']['hw_type'] == hw_type and ald['ald']['hw_instance'] == hw_instance]
        return [ald['ald'] for ald in self._attributes.values() if ald['ald']['hw_type'] == hw_type]

    def get_all_rfs(self):
        """Method is used to get all RFs configuration.
        :return: list of all rfs
        :rtype: list
        """
        return self._attributes.values()

    def get_all_alds(self):
        """Method is used to get all ALDs configuration attached in RF.
        :return: list f all alds
        :rtype: list
        """
        return [ald['ald'] for ald in self._attributes.values()]


class UTE_CONFIG(Config):
    """This class describes the UTE testline configuration parameters."""

    HW_TYPE_MAPPINGS = {'FSMr3': 'FSMF'}
    VALIDATOR = Or(IsInstance(GROUP_CONFIG), IsInstance(type(None)), IsInstance(list), IsInstance(tuple))

    def __init__(self, host=None, fsm=None, iphy=None, rf=None, los=None, ue=None, rfs=None, rtg=None, cus=None):
        """
        :param host:  Host configuration/s.
        :param fsm:   FSM configuration/s.
        :param iphy:  IPHY configuration/s.
        :param rf:    RF configuration/s.
        :param los:   Optical Switch configuration/s.
        :param ue:    UE configuration/s.
        :param rtg:   RTG configuration/s.
        :param cus:   CUS configuration/s.
        """
        super(UTE_CONFIG, self).__init__()

        host = self._to_tuple(host)
        fsm = self._to_tuple(fsm)
        iphy = self._to_tuple(iphy)
        rf = self._to_tuple(rf)
        rfs = self._to_tuple(rfs, True)
        los = self._to_tuple(los)
        ue = self._to_tuple(ue)
        rtg = self._to_tuple(rtg)
        cus = self._to_tuple(cus)

        self._set_attr('host', host, self.VALIDATOR)
        self._set_attr('fsm', fsm, self.VALIDATOR)
        self._set_attr('iphy', iphy, self.VALIDATOR)
        self._set_attr('rf', rf, self.VALIDATOR)
        self._set_attr('rfs', rfs, self.VALIDATOR)
        self._set_attr('los', los, self.VALIDATOR)
        self._set_attr('ue', ue, self.VALIDATOR)
        self._set_attr('rtg', rtg, self.VALIDATOR)
        self._set_attr('cus', cus, self.VALIDATOR)

        # temporary solution due to single eNB backwards compatibility
        if self._attributes['fsm']:
            self._add_attrs_like_in_ute_wmp()
        if self._attributes['host']:
            self._set_attr('host_ip', self._attributes['host'][1]['addr'])

        self._set_attr('iphy_pdu_outlet', self._attributes['iphy'][1]['pdu']['port'] if self._attributes['iphy'] else None)

        # temporary solution due to multi eNB backwards compatibility
        # if len(self._attributes['host']) > 0 and len(self._attributes['fsm']) > 0 and len(self._attributes['iphy']) > 0:
        if self._attributes['host'] and self._attributes['fsm']:
            self._ensure_multi_enb_backwards_compatibility(self._config_zip(iphy))

    def _ensure_multi_enb_backwards_compatibility(self, config):
        index = 1
        for host, fsm, iphy in config:
            self._set_attr(index, self._create_ute_wmp(host, fsm, iphy))
            index += 1

    def _config_zip(self, iphy):
        if len(tuple(iphy)) > 0:
            return list(zip(self._attributes['host'], self._attributes['fsm'], self._attributes['iphy']))
        return zip_longest(self._attributes['host'], self._attributes['fsm'], self._attributes['iphy'])

    def __getitem__(self, item):
        return self._attributes[item]

    def __iter__(self):
        return iter(self._attributes[i] for i in sorted(self._valid_indices()))

    def __len__(self):
        return len(self._valid_indices())

    def _valid_indices(self):
        return [i for i in self._attributes.keys() if isinstance(i, int)]

    def _to_tuple(self, item, is_rfs=False):
        if isinstance(item, TrsSchemas):
            return dict(item)
        elif isinstance(item, (list, tuple)):
            return RF_CONFIG(*item) if is_rfs else GROUP_CONFIG(*item)
        elif isinstance(item, GROUP_CONFIG):
            return item
        elif isinstance(item, Config):
            return RF_CONFIG(item) if is_rfs else GROUP_CONFIG(item)
        return ()

    def _add_attrs_like_in_ute_wmp(self):
        self._set_attr('enb_hw_type', self.HW_TYPE_MAPPINGS.get(self._attributes['fsm'][1]['hw_type'], self._attributes['fsm'][1]['hw_type']))
        self._set_attr('pdu_ip', self._attributes['fsm'][1]['pdu']['addr'])
        self._set_attr('pdu_type', self._attributes['fsm'][1]['pdu']['device'])
        self._set_attr('enb_pdu_outlet', self._attributes['fsm'][1]['pdu']['port'])
        self._set_attr('bbmod1_pdu_outlet', self._read_optional_value(self._attributes['fsm'][1], ['bbmod1_pdu', 'port']))
        self._set_attr('bbmod2_pdu_outlet', self._read_optional_value(self._attributes['fsm'][1], ['bbmod2_pdu', 'port']))
        self._set_attr('top_ip', self._attributes['fsm'][1]['top_ip'])
        self._set_attr('vlan_ids', self._attributes['fsm'][1]['vlan_ids'])
        if self._attributes['fsm'][1]['trs_ip'] == '10.0.1.4':
            trs_ips = TrsSchema2()
        elif self._attributes['fsm'][1]['trs_ip'] == '10.0.1.6':
            trs_ips = TrsSchema3()
        else:
            trs_ips = TrsSchema1()
        trs_ips['iphy'] = trs_ips['iphy'] if self._attributes['iphy'] else None
        self._set_attr('trs_ips', trs_ips)

    def _create_ute_wmp(self, host, fsm, iphy):
        trs_ips = TrsSchema1()
        if self._hasattr(fsm, 'trs_ip'):
            if getattr(fsm, 'trs_ip') == '10.0.1.4':
                trs_ips = TrsSchema2()
            elif getattr(fsm, 'trs_ip') == '10.0.1.6':
                trs_ips = TrsSchema3()
        trs_ips['iphy'] = trs_ips['iphy'] if iphy else None
        return UTE_WMP(enb_hw_type=self.HW_TYPE_MAPPINGS.get(fsm['hw_type'], fsm['hw_type']),
                       pdu_ip=fsm['pdu']['addr'],
                       pdu_type=fsm['pdu']['device'],
                       enb_pdu_outlet=fsm['pdu']['port'],
                       iphy_pdu_outlet=iphy['pdu']['port'] if iphy else None,
                       iphy_pdu_ip=iphy['pdu']['addr'] if iphy else None,
                       iphy_pdu_type=iphy['pdu']['device'] if iphy else None,
                       bbmod1_pdu_outlet=self._read_optional_value(fsm, ['bbmod1_pdu', 'port']),
                       bbmod2_pdu_outlet=self._read_optional_value(fsm, ['bbmod2_pdu', 'port']),
                       host_ip=self._read_optional_value(host, ['addr'], '127.0.0.1'),
                       top_ip=fsm['top_ip'],
                       vlan_ids=fsm['vlan_ids'],
                       trs_ips=trs_ips)

    def _read_optional_value(self, obj, attrs, default=None):
        result = obj
        for attr in attrs:
            if self._hasattr(result, attr):
                result = getattr(result, attr)
            else:
                result = default
        return result

    def _hasattr(self, module, attr):
        try:
            return hasattr(module, attr)
        except KeyError:
            return False


class Host(Config):
    def __init__(self, addr='127.0.0.1', username='ute', password='ute'):
        super(Host, self).__init__()

        self._set_attr('addr', addr, Or(IsIpAddress(), IsFqdn()))
        self._set_attr('username', username, IsNotEmpty())
        self._set_attr('password', password, IsNotEmpty())


class Pdu(PduMixin):
    def __init__(self, addr, port, device, **kwargs):
        super(Pdu, self).__init__()

        self.device = device
        self.port = port
        self.addr = addr
        self.kwargs = kwargs

        self.pdu_addr_validator = IsIpAddress()
        self.pdu_device_validator = IsOneOf(*self.PDU_TYPES_ALLOWED)
        self.pdu_port_validator = IsOneOf(*self.get_allowed_pdu_outlets(self.device))
        self.pdu_snmp_user_validator = Or(IsInstance(type(None)), And(IsInstance(dict), IsNotEmpty()))
        self.pdu_protocol_validator = Or(IsInstance(type(None)), IsOneOf(*self.PROTOCOLS_ALLOWED))
        self.pdu_proxy_validator = Or(IsInstance(type(None)), IsIpv4Proxy())

        self.validator = {
            "protocol": self.pdu_protocol_validator,
            "snmp_user": self.pdu_snmp_user_validator,
            "http_proxy": self.pdu_proxy_validator
        }

        self._set_mandatory_parameters()
        if self.kwargs:
            self._set_optional_parameters()

    def _set_mandatory_parameters(self):
        self._set_attr('addr', self.addr, self.pdu_addr_validator)
        self._set_attr('port', self.port, self.pdu_port_validator)
        self._set_attr('device', self.device, self.pdu_device_validator)

    def _set_optional_parameters(self):
        for param, value in self.kwargs.items():
            if param not in ("protocol", "snmp_user", "http_proxy"):
                self._set_attr(param, value)
            else:
                self._set_attr(param, value, self.validator[param])


class FSMr3(FSMConfig):
    def __init__(self, pdu, bbmod1_pdu=None, bbmod2_pdu=None, trs_ip='10.0.1.2', top_ip='10.44.136.254', vlan_ids=None,
                 oam_ip='10.0.1.1'):
        super(FSMr3, self).__init__()

        self._set_attr('hw_type', self.__class__.__name__)
        self._set_attr('pdu', pdu, IsInstance(Pdu))
        self._set_attr('bbmod1_pdu', bbmod1_pdu, Or(IsInstance(Pdu), IsInstance(type(None))))
        self._set_attr('bbmod2_pdu', bbmod2_pdu, Or(IsInstance(Pdu), IsInstance(type(None))))
        self._set_attr('trs_ip', trs_ip, IsIpAddress())
        self._set_attr('top_ip', top_ip, IsIpAddress())
        self._set_attr('vlan_ids', vlan_ids, self.vlan_id_validator(vlan_ids))
        self._set_attr('oam_ip', oam_ip, IsIpAddress())


class FSMr4(FSMConfig):
    def __init__(self, hw_type, pdu, hw_version='X21', fbip1=None, fbip2=None, fbip3=None,
                 trs_ip='10.0.1.2', top_ip='10.44.136.254', vlan_ids=None, trs_ips=None, oam_ip='10.0.1.1'):
        super(FSMr4, self).__init__()

        device_version_allowed = ["X12", "X21", "X31", "Y32", "A101", "A102", "A203"]

        self._set_attr('hw_type', hw_type)
        self._set_attr('hw_version', hw_version, IsOneOf(*device_version_allowed))
        self._set_attr('pdu', pdu, IsInstance(Pdu))
        self._set_attr('fbip1', fbip1, Or(IsInstance(bool), IsInstance(type(None))))
        self._set_attr('fbip2', fbip2, Or(IsInstance(bool), IsInstance(type(None))))
        self._set_attr('fbip3', fbip3, Or(IsInstance(bool), IsInstance(type(None))))
        self._set_attr('trs_ip', trs_ip, IsIpAddress())
        self._set_attr('top_ip', top_ip, IsIpAddress())
        self._set_attr('vlan_ids', vlan_ids, self.vlan_id_validator(vlan_ids))
        self._set_attr('trs_ips', trs_ips, Or(IsIpAddress(), IsInstance(Config))) \
            if trs_ips else self._set_attr('trs_ips', TrsSchema1(), IsInstance(Config))
        self._set_attr('oam_ip', oam_ip, IsIpAddress())


